INSERT INTO post (id, member_id, content, file_url, like_count, subscriber_only, created_at, updated_at) VALUES
  (1, 1, '한강공원에 조금 일찍 나와 30분을 걸었다. 밤새 내린 비 덕분에 공기가 유난히 맑았다 #아침기록 #산책', NULL, 1, FALSE, '2026-09-01 10:01:00', '2026-09-01 10:01:00'),
  (2, 2, '성수동 골목에 조금 일찍 나와 30분을 걸었다. 은행잎 색이 하루 사이 더 짙어졌다 #아침기록 #산책', NULL, 1, FALSE, '2026-09-02 11:02:00', '2026-09-02 11:02:00'),
  (3, 3, '집 근처 하천길에 조금 일찍 나와 30분을 걸었다. 문을 여는 가게들의 소리가 정겹게 들렸다 #아침기록 #산책', NULL, 1, FALSE, '2026-09-03 12:03:00', '2026-09-03 12:03:00'),
