  (51, 1, '오늘 저녁은 들기름 막국수. 냉장고에 남은 재료를 모아 만들었는데 예상보다 조합이 좋았다 잘 먹은 한 끼는 하루를 꽤 다정하게 마무리해 준다. #집밥 #오늘의식탁', NULL, 1, FALSE, '2026-09-11 12:51:00', '2026-09-11 12:51:00'),
  (52, 2, '오늘 저녁은 토마토 바질 파스타. 간을 평소보다 약하게 했더니 재료 맛이 더 잘 느껴졌다 잘 먹은 한 끼는 하루를 꽤 다정하게 마무리해 준다. #집밥 #오늘의식탁', 'https://cdn.example.com/files/post-52.bin', 1, FALSE, '2026-09-12 13:52:00', '2026-09-12 13:52:00'),
  (53, 3, '오늘 저녁은 묵은지 김치찜. 레시피에서 설탕을 줄이고 양파를 오래 볶아 단맛을 냈다 잘 먹은 한 끼는 하루를 꽤 다정하게 마무리해 준다. #집밥 #오늘의식탁', NULL, 1, FALSE, '2026-09-13 14:53:00', '2026-09-13 14:53:00'),
  (54, 4, '오늘 저녁은 버섯 솥밥. 처음 시도한 메뉴라 걱정했지만 접시를 깨끗이 비웠다 잘 먹은 한 끼는 하루를 꽤 다정하게 마무리해 준다. #집밥 #오늘의식탁', NULL, 1, TRUE, '2026-09-14 15:54:00', '2026-09-14 15:54:00'),
  (55, 5, '오늘 저녁은 두부 유부초밥. 시장 상인분이 알려주신 방법대로 했더니 식감이 훨씬 좋았다 잘 먹은 한 끼는 하루를 꽤 다정하게 마무리해 준다. #집밥 #오늘의식탁', NULL, 1, FALSE, '2026-09-15 16:55:00', '2026-09-15 16:55:00'),
  (56, 6, '오늘 저녁은 바질 페스토 샌드위치. 바쁜 저녁에도 20분이면 만들 수 있어 자주 해 먹을 것 같다 잘 먹은 한 끼는 하루를 꽤 다정하게 마무리해 준다. #집밥 #오늘의식탁', 'https://cdn.example.com/files/post-56.bin', 1, FALSE, '2026-09-16 17:56:00', '2026-09-16 17:56:00'),
  (57, 7, '오늘 저녁은 새우 오일 파스타. 그릇까지 따뜻하게 데워 담으니 마지막 한입까지 온기가 남았다 잘 먹은 한 끼는 하루를 꽤 다정하게 마무리해 준다. #집밥 #오늘의식탁', NULL, 1, FALSE, '2026-09-17 18:57:00', '2026-09-17 18:57:00'),
  (58, 8, '오늘 저녁은 단호박 수프. 매운맛을 조금 줄였더니 가족 모두 편하게 먹었다 잘 먹은 한 끼는 하루를 꽤 다정하게 마무리해 준다. #집밥 #오늘의식탁', NULL, 1, FALSE, '2026-09-18 19:58:00', '2026-09-18 19:58:00'),
