  (102, 2, '이번 주 읽은 책의 메모을 마무리했다. 작은 진전이라도 매일 쌓이는 힘을 다시 느꼈다 과정의 흔적도 오래 기억하고 싶어 남겨 둔다. #작업기록', NULL, 1, TRUE, '2026-09-02 15:42:00', '2026-09-02 15:42:00'),
  (103, 3, '새로 배운 촬영 방식으로 찍은 사진을 마무리했다. 생각한 결과와 달랐지만 우연히 생긴 부분이 오히려 마음에 든다 과정의 흔적도 오래 기억하고 싶어 남겨 둔다. #작업기록', NULL, 1, FALSE, '2026-09-03 16:43:00', '2026-09-03 16:43:00'),
