  (146, 46, '처음 구운 사워도우 한 덩이을 마무리했다. 오늘은 여기까지. 멈출 곳을 정하는 것도 작업의 일부였다 과정의 흔적도 오래 기억하고 싶어 남겨 둔다. #작업기록', NULL, 1, FALSE, '2026-09-06 11:26:00', '2026-09-06 11:26:00'),
  (147, 47, '주말에 만든 작은 도자기 컵을 마무리했다. 완벽하게 시작하려는 마음을 내려놓으니 다음 단계가 보였다 과정의 흔적도 오래 기억하고 싶어 남겨 둔다. #작업기록', NULL, 1, FALSE, '2026-09-07 12:27:00', '2026-09-07 12:27:00'),
  (148, 48, '최근 정리한 러닝 훈련 기록을 마무리했다. 작은 진전이라도 매일 쌓이는 힘을 다시 느꼈다 과정의 흔적도 오래 기억하고 싶어 남겨 둔다. #작업기록', 'https://cdn.example.com/files/post-148.bin', 1, FALSE, '2026-09-08 13:28:00', '2026-09-08 13:28:00'),
  (149, 49, '직접 고친 빈티지 스툴을 마무리했다. 생각한 결과와 달랐지만 우연히 생긴 부분이 오히려 마음에 든다 과정의 흔적도 오래 기억하고 싶어 남겨 둔다. #작업기록', NULL, 1, FALSE, '2026-09-09 14:29:00', '2026-09-09 14:29:00'),
  (150, 50, '연습 중인 드로잉 한 장을 마무리했다. 피드백을 받고 고친 뒤 훨씬 편안한 모양이 되었다 과정의 흔적도 오래 기억하고 싶어 남겨 둔다. #작업기록', NULL, 1, TRUE, '2026-09-10 15:30:00', '2026-09-10 15:30:00'),
  (151, 1, '강릉 안목해변에서 보낸 하루. 아침 첫차로 도착해 사람이 적을 때 천천히 둘러봤다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-11 16:31:00', '2026-09-11 16:31:00'),
  (152, 2, '전주 한옥마을 뒤편 골목에서 보낸 하루. 관광지에서 한 블록 벗어나니 조용한 동네 풍경이 이어졌다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', 'https://cdn.example.com/files/post-152.bin', 1, FALSE, '2026-09-12 17:32:00', '2026-09-12 17:32:00'),
  (153, 3, '부산 영도 흰여울길에서 보낸 하루. 현지 분이 추천해 준 작은 식당에서 든든하게 한 끼를 먹었다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-13 18:33:00', '2026-09-13 18:33:00'),
  (154, 4, '제주 비자림에서 보낸 하루. 해 질 무렵 빛이 좋아 한참 같은 자리에 머물렀다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-14 19:34:00', '2026-09-14 19:34:00'),
  (155, 5, '경주 황리단길에서 보낸 하루. 계획 없이 걷다가 마음에 드는 책방을 발견했다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-15 20:35:00', '2026-09-15 20:35:00'),
