  (186, 36, '통영 중앙시장에서 보낸 하루. 바람이 세서 계획을 바꿨지만 덕분에 새로운 길을 만났다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, TRUE, '2026-09-06 15:06:00', '2026-09-06 15:06:00'),
  (187, 37, '속초 영랑호에서 보낸 하루. 휴대폰을 가방에 넣고 풍경을 눈으로 오래 담았다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-07 16:07:00', '2026-09-07 16:07:00'),
  (188, 38, '여수 돌산 해안도로에서 보낸 하루. 아침 첫차로 도착해 사람이 적을 때 천천히 둘러봤다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', 'https://cdn.example.com/files/post-188.bin', 1, FALSE, '2026-09-08 17:08:00', '2026-09-08 17:08:00'),
  (189, 39, '군산 월명동에서 보낸 하루. 관광지에서 한 블록 벗어나니 조용한 동네 풍경이 이어졌다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-09 18:09:00', '2026-09-09 18:09:00'),
  (190, 40, '춘천 의암호에서 보낸 하루. 현지 분이 추천해 준 작은 식당에서 든든하게 한 끼를 먹었다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-10 19:10:00', '2026-09-10 19:10:00'),
  (191, 41, '강릉 안목해변에서 보낸 하루. 계획 없이 걷다가 마음에 드는 책방을 발견했다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-11 20:11:00', '2026-09-11 20:11:00'),
  (192, 42, '전주 한옥마을 뒤편 골목에서 보낸 하루. 비가 잠깐 내려 처마 아래서 쉬어 간 시간까지 좋았다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', 'https://cdn.example.com/files/post-192.bin', 1, TRUE, '2026-09-12 09:12:00', '2026-09-12 09:12:00'),
