  (197, 47, '속초 영랑호에서 보낸 하루. 아침 첫차로 도착해 사람이 적을 때 천천히 둘러봤다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-17 14:17:00', '2026-09-17 14:17:00'),
  (198, 48, '여수 돌산 해안도로에서 보낸 하루. 관광지에서 한 블록 벗어나니 조용한 동네 풍경이 이어졌다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, TRUE, '2026-09-18 15:18:00', '2026-09-18 15:18:00'),
  (199, 49, '군산 월명동에서 보낸 하루. 현지 분이 추천해 준 작은 식당에서 든든하게 한 끼를 먹었다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', NULL, 1, FALSE, '2026-09-19 16:19:00', '2026-09-19 16:19:00'),
  (200, 50, '춘천 의암호에서 보낸 하루. 해 질 무렵 빛이 좋아 한참 같은 자리에 머물렀다 유명한 장소보다 그 사이의 평범한 풍경이 더 오래 기억에 남는다. #국내여행 #여행기록', 'https://cdn.example.com/files/post-200.bin', 1, FALSE, '2026-09-20 17:20:00', '2026-09-20 17:20:00'),
  (201, 1, '이번 주는 해야 할 일보다 하지 않아도 될 일을 덜어내는 데 집중했다. 비워 낸 자리 덕분에 정말 중요한 일이 또렷해졌다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-01 18:21:00', '2026-09-01 18:21:00'),
  (202, 2, '요즘 하루를 마치기 전에 좋았던 일 세 가지를 적고 있다. 사소한 문장들이 쌓이니 평범한 날도 꽤 괜찮았다는 걸 알게 된다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-02 19:22:00', '2026-09-02 19:22:00'),
  (203, 3, '오랜만에 아무 약속 없는 저녁을 집에서 보냈다. 조용한 시간이 생각보다 큰 회복이 되었다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-03 20:23:00', '2026-09-03 20:23:00'),
  (204, 4, '최근에는 빠른 답보다 정확한 질문을 찾으려 한다. 서두르지 않아도 방향을 잃지 않는 연습이 필요하다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', 'https://cdn.example.com/files/post-204.bin', 1, TRUE, '2026-09-04 09:24:00', '2026-09-04 09:24:00'),
  (205, 5, '계절이 바뀔 때마다 옷장과 마음을 함께 정리한다. 정리는 버리는 일이 아니라 앞으로의 선택을 가볍게 만드는 일 같다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-05 10:25:00', '2026-09-05 10:25:00'),
  (206, 6, '한동안 멈췄던 취미를 다시 시작했다. 손이 기억하고 있어서 금세 즐거움이 돌아왔다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-06 11:26:00', '2026-09-06 11:26:00'),
  (207, 7, '바쁜 날일수록 점심시간만큼은 화면을 보지 않기로 했다. 짧은 산책과 따뜻한 식사가 오후의 집중력을 바꿔 놓았다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-07 12:27:00', '2026-09-07 12:27:00'),
  (208, 8, '예전 사진을 정리하다 잊고 있던 장면을 많이 발견했다. 사진 속 표정보다 그날의 공기와 대화가 먼저 떠올랐다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', 'https://cdn.example.com/files/post-208.bin', 1, FALSE, '2026-09-08 13:28:00', '2026-09-08 13:28:00'),
  (209, 9, '오늘 회의에서 솔직하게 모른다고 말해 보았다. 도움을 구할 수 있는 것도 실력이라는 말을 조금 이해했다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-09 14:29:00', '2026-09-09 14:29:00'),
  (210, 10, '주말 동안 알림을 꺼 두고 충분히 쉬었다. 쉬고 나니 미뤄 둔 일에 다시 손을 댈 여유가 생겼다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, TRUE, '2026-09-10 15:30:00', '2026-09-10 15:30:00'),
  (211, 11, '이번 주는 해야 할 일보다 하지 않아도 될 일을 덜어내는 데 집중했다. 사소한 문장들이 쌓이니 평범한 날도 꽤 괜찮았다는 걸 알게 된다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-11 16:31:00', '2026-09-11 16:31:00'),
