  (227, 27, '바쁜 날일수록 점심시간만큼은 화면을 보지 않기로 했다. 도움을 구할 수 있는 것도 실력이라는 말을 조금 이해했다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-07 20:47:00', '2026-09-07 20:47:00'),
  (228, 28, '예전 사진을 정리하다 잊고 있던 장면을 많이 발견했다. 쉬고 나니 미뤄 둔 일에 다시 손을 댈 여유가 생겼다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', 'https://cdn.example.com/files/post-228.bin', 1, TRUE, '2026-09-08 09:48:00', '2026-09-08 09:48:00'),
  (229, 29, '오늘 회의에서 솔직하게 모른다고 말해 보았다. 비워 낸 자리 덕분에 정말 중요한 일이 또렷해졌다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-09 10:49:00', '2026-09-09 10:49:00'),
  (230, 30, '주말 동안 알림을 꺼 두고 충분히 쉬었다. 사소한 문장들이 쌓이니 평범한 날도 꽤 괜찮았다는 걸 알게 된다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-10 11:50:00', '2026-09-10 11:50:00'),
  (231, 31, '이번 주는 해야 할 일보다 하지 않아도 될 일을 덜어내는 데 집중했다. 서두르지 않아도 방향을 잃지 않는 연습이 필요하다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-11 12:51:00', '2026-09-11 12:51:00'),
  (232, 32, '요즘 하루를 마치기 전에 좋았던 일 세 가지를 적고 있다. 정리는 버리는 일이 아니라 앞으로의 선택을 가볍게 만드는 일 같다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', 'https://cdn.example.com/files/post-232.bin', 1, FALSE, '2026-09-12 13:52:00', '2026-09-12 13:52:00'),
  (233, 33, '오랜만에 아무 약속 없는 저녁을 집에서 보냈다. 손이 기억하고 있어서 금세 즐거움이 돌아왔다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-13 14:53:00', '2026-09-13 14:53:00'),
  (234, 34, '최근에는 빠른 답보다 정확한 질문을 찾으려 한다. 짧은 산책과 따뜻한 식사가 오후의 집중력을 바꿔 놓았다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, TRUE, '2026-09-14 15:54:00', '2026-09-14 15:54:00'),
  (235, 35, '계절이 바뀔 때마다 옷장과 마음을 함께 정리한다. 사진 속 표정보다 그날의 공기와 대화가 먼저 떠올랐다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-15 16:55:00', '2026-09-15 16:55:00'),
  (236, 36, '한동안 멈췄던 취미를 다시 시작했다. 도움을 구할 수 있는 것도 실력이라는 말을 조금 이해했다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', 'https://cdn.example.com/files/post-236.bin', 1, FALSE, '2026-09-16 17:56:00', '2026-09-16 17:56:00'),
  (237, 37, '바쁜 날일수록 점심시간만큼은 화면을 보지 않기로 했다. 쉬고 나니 미뤄 둔 일에 다시 손을 댈 여유가 생겼다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-17 18:57:00', '2026-09-17 18:57:00'),
