  (239, 39, '오늘 회의에서 솔직하게 모른다고 말해 보았다. 사소한 문장들이 쌓이니 평범한 날도 꽤 괜찮았다는 걸 알게 된다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-19 20:59:00', '2026-09-19 20:59:00'),
  (240, 40, '주말 동안 알림을 꺼 두고 충분히 쉬었다. 조용한 시간이 생각보다 큰 회복이 되었다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', 'https://cdn.example.com/files/post-240.bin', 1, TRUE, '2026-09-20 09:00:00', '2026-09-20 09:00:00'),
