  (249, 49, '오늘 회의에서 솔직하게 모른다고 말해 보았다. 조용한 시간이 생각보다 큰 회복이 되었다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-09 18:09:00', '2026-09-09 18:09:00'),
  (250, 50, '주말 동안 알림을 꺼 두고 충분히 쉬었다. 서두르지 않아도 방향을 잃지 않는 연습이 필요하다 이번 주의 마음을 잊지 않으려고 짧게 기록해 둔다.', NULL, 1, FALSE, '2026-09-10 19:10:00', '2026-09-10 19:10:00'),
  (251, 1, '서울에서 조용히 책 읽기 좋은 카페을 찾고 있습니다. 콘센트보다 편안한 의자와 너무 크지 않은 음악이 중요해요 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', NULL, 1, FALSE, '2026-09-11 20:11:00', '2026-09-11 20:11:00'),
  (252, 2, '초보자가 걷기 좋은 가을 등산 코스을 찾고 있습니다. 대중교통으로 갈 수 있고 3시간 안쪽이면 좋겠습니다 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', 'https://cdn.example.com/files/post-252.bin', 1, TRUE, '2026-09-12 09:12:00', '2026-09-12 09:12:00'),
  (253, 3, '집에서 키우기 쉬운 반려식물을 찾고 있습니다. 오전 햇빛이 두 시간 정도 드는 작은 창가가 있어요 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', NULL, 1, FALSE, '2026-09-13 10:13:00', '2026-09-13 10:13:00'),
  (254, 4, '비 오는 날 듣기 좋은 앨범을 찾고 있습니다. 재즈나 잔잔한 인디 음악을 자주 듣습니다 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', NULL, 1, FALSE, '2026-09-14 11:14:00', '2026-09-14 11:14:00'),
  (255, 5, '주말에 가기 좋은 독립서점을 찾고 있습니다. 책 큐레이션이 분명하고 근처에 산책할 곳도 있으면 좋겠어요 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', NULL, 1, FALSE, '2026-09-15 12:15:00', '2026-09-15 12:15:00'),
  (256, 6, '입문용 필름 카메라을 찾고 있습니다. 가볍게 들고 다닐 수 있고 조작이 단순한 모델을 찾고 있어요 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', 'https://cdn.example.com/files/post-256.bin', 1, FALSE, '2026-09-16 13:16:00', '2026-09-16 13:16:00'),
  (257, 7, '혼자 먹기 좋은 따뜻한 저녁 메뉴을 찾고 있습니다. 조리 시간이 30분을 넘지 않는 레시피면 더 좋습니다 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', NULL, 1, FALSE, '2026-09-17 14:17:00', '2026-09-17 14:17:00'),
  (258, 8, '서울 근교 자전거 코스을 찾고 있습니다. 차량 통행이 적고 중간에 쉬어 갈 곳이 있는 길을 원해요 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', NULL, 1, TRUE, '2026-09-18 15:18:00', '2026-09-18 15:18:00'),
  (259, 9, '처음 배우기 좋은 뜨개 소품을 찾고 있습니다. 목도리보다 짧은 시간 안에 완성할 수 있으면 좋겠어요 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', NULL, 1, FALSE, '2026-09-19 16:19:00', '2026-09-19 16:19:00'),
  (260, 10, '일상 기록에 쓰기 좋은 작은 노트을 찾고 있습니다. 만년필 번짐이 적고 한 손에 들어오는 크기를 선호합니다 최근 다녀오거나 써 본 곳이 있다면 알려주세요 🙂', 'https://cdn.example.com/files/post-260.bin', 1, FALSE, '2026-09-20 17:20:00', '2026-09-20 17:20:00'),
  (261, 11, '서울에서 조용히 책 읽기 좋은 카페을 찾고 있습니다. 콘센트보다 편안한 의자와 너무 크지 않은 음악이 중요해요 직접 경험한 추천을 듣고 싶어요 🙂', NULL, 1, FALSE, '2026-09-01 18:21:00', '2026-09-01 18:21:00'),
  (262, 12, '초보자가 걷기 좋은 가을 등산 코스을 찾고 있습니다. 대중교통으로 갈 수 있고 3시간 안쪽이면 좋겠습니다 직접 경험한 추천을 듣고 싶어요 🙂', NULL, 1, FALSE, '2026-09-02 19:22:00', '2026-09-02 19:22:00'),
