  (274, 24, '비 오는 날 듣기 좋은 앨범을 찾고 있습니다. 재즈나 잔잔한 인디 음악을 자주 듣습니다 작은 팁이라도 편하게 나눠 주세요 🙂', NULL, 1, FALSE, '2026-09-14 19:34:00', '2026-09-14 19:34:00'),
  (275, 25, '주말에 가기 좋은 독립서점을 찾고 있습니다. 책 큐레이션이 분명하고 근처에 산책할 곳도 있으면 좋겠어요 작은 팁이라도 편하게 나눠 주세요 🙂', NULL, 1, FALSE, '2026-09-15 20:35:00', '2026-09-15 20:35:00'),
  (276, 26, '입문용 필름 카메라을 찾고 있습니다. 가볍게 들고 다닐 수 있고 조작이 단순한 모델을 찾고 있어요 작은 팁이라도 편하게 나눠 주세요 🙂', 'https://cdn.example.com/files/post-276.bin', 1, TRUE, '2026-09-16 09:36:00', '2026-09-16 09:36:00'),
  (277, 27, '혼자 먹기 좋은 따뜻한 저녁 메뉴을 찾고 있습니다. 조리 시간이 30분을 넘지 않는 레시피면 더 좋습니다 작은 팁이라도 편하게 나눠 주세요 🙂', NULL, 1, FALSE, '2026-09-17 10:37:00', '2026-09-17 10:37:00'),
  (278, 28, '서울 근교 자전거 코스을 찾고 있습니다. 차량 통행이 적고 중간에 쉬어 갈 곳이 있는 길을 원해요 작은 팁이라도 편하게 나눠 주세요 🙂', NULL, 1, FALSE, '2026-09-18 11:38:00', '2026-09-18 11:38:00'),
  (279, 29, '처음 배우기 좋은 뜨개 소품을 찾고 있습니다. 목도리보다 짧은 시간 안에 완성할 수 있으면 좋겠어요 작은 팁이라도 편하게 나눠 주세요 🙂', NULL, 1, FALSE, '2026-09-19 12:39:00', '2026-09-19 12:39:00'),
  (280, 30, '일상 기록에 쓰기 좋은 작은 노트을 찾고 있습니다. 만년필 번짐이 적고 한 손에 들어오는 크기를 선호합니다 작은 팁이라도 편하게 나눠 주세요 🙂', 'https://cdn.example.com/files/post-280.bin', 1, FALSE, '2026-09-20 13:40:00', '2026-09-20 13:40:00'),
  (281, 31, '서울에서 조용히 책 읽기 좋은 카페을 찾고 있습니다. 콘센트보다 편안한 의자와 너무 크지 않은 음악이 중요해요 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', NULL, 1, FALSE, '2026-09-01 14:41:00', '2026-09-01 14:41:00'),
  (282, 32, '초보자가 걷기 좋은 가을 등산 코스을 찾고 있습니다. 대중교통으로 갈 수 있고 3시간 안쪽이면 좋겠습니다 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', NULL, 1, TRUE, '2026-09-02 15:42:00', '2026-09-02 15:42:00'),
  (283, 33, '집에서 키우기 쉬운 반려식물을 찾고 있습니다. 오전 햇빛이 두 시간 정도 드는 작은 창가가 있어요 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', NULL, 1, FALSE, '2026-09-03 16:43:00', '2026-09-03 16:43:00'),
  (284, 34, '비 오는 날 듣기 좋은 앨범을 찾고 있습니다. 재즈나 잔잔한 인디 음악을 자주 듣습니다 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', 'https://cdn.example.com/files/post-284.bin', 1, FALSE, '2026-09-04 17:44:00', '2026-09-04 17:44:00'),
  (285, 35, '주말에 가기 좋은 독립서점을 찾고 있습니다. 책 큐레이션이 분명하고 근처에 산책할 곳도 있으면 좋겠어요 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', NULL, 1, FALSE, '2026-09-05 18:45:00', '2026-09-05 18:45:00'),
  (286, 36, '입문용 필름 카메라을 찾고 있습니다. 가볍게 들고 다닐 수 있고 조작이 단순한 모델을 찾고 있어요 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', NULL, 1, FALSE, '2026-09-06 19:46:00', '2026-09-06 19:46:00'),
  (287, 37, '혼자 먹기 좋은 따뜻한 저녁 메뉴을 찾고 있습니다. 조리 시간이 30분을 넘지 않는 레시피면 더 좋습니다 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', NULL, 1, FALSE, '2026-09-07 20:47:00', '2026-09-07 20:47:00'),
  (288, 38, '서울 근교 자전거 코스을 찾고 있습니다. 차량 통행이 적고 중간에 쉬어 갈 곳이 있는 길을 원해요 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', 'https://cdn.example.com/files/post-288.bin', 1, TRUE, '2026-09-08 09:48:00', '2026-09-08 09:48:00'),
  (289, 39, '처음 배우기 좋은 뜨개 소품을 찾고 있습니다. 목도리보다 짧은 시간 안에 완성할 수 있으면 좋겠어요 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', NULL, 1, FALSE, '2026-09-09 10:49:00', '2026-09-09 10:49:00'),
  (290, 40, '일상 기록에 쓰기 좋은 작은 노트을 찾고 있습니다. 만년필 번짐이 적고 한 손에 들어오는 크기를 선호합니다 저장해 두고 하나씩 찾아가 보려고 합니다 🙂', NULL, 1, FALSE, '2026-09-10 11:50:00', '2026-09-10 11:50:00'),
