  (35, 35, 42, '아침에 몸을 조금 움직이면 하루가 훨씬 또렷해지는 느낌이에요.나중에 다녀오신 후기도 기다릴게요.', 1, '2026-09-15 12:35:00', '2026-09-15 12:35:00'),
  (36, 36, 43, '비 온 다음 날 산책은 공기부터 다르죠. 글을 읽으니 저도 걷고 싶어졌어요.나중에 다녀오신 후기도 기다릴게요.', 1, '2026-09-16 12:36:00', '2026-09-16 12:36:00'),
