  (244, 244, 1, '쉬는 시간을 일부러 일정에 넣는 것도 필요한 것 같아요.좋은 이야기 나눠 주셔서 고맙습니다.', 0, '2026-09-04 12:04:00', '2026-09-04 12:04:00'),
  (245, 245, 2, '모른다고 말할 수 있는 용기가 팀을 더 건강하게 만든다고 생각해요.좋은 이야기 나눠 주셔서 고맙습니다.', 0, '2026-09-05 12:05:00', '2026-09-05 12:05:00'),
  (246, 246, 3, '평범한 하루를 돌아보게 하는 다정한 기록이네요.좋은 이야기 나눠 주셔서 고맙습니다.', 0, '2026-09-06 12:06:00', '2026-09-06 12:06:00'),
  (247, 247, 4, '빠른 답보다 좋은 질문이 중요하다는 말에 깊이 공감합니다.좋은 이야기 나눠 주셔서 고맙습니다.', 0, '2026-09-07 12:07:00', '2026-09-07 12:07:00'),
  (248, 248, 5, '알림을 꺼 두는 것만으로도 마음이 꽤 조용해지더라고요.좋은 이야기 나눠 주셔서 고맙습니다.', 0, '2026-09-08 12:08:00', '2026-09-08 12:08:00'),
  (249, 249, 6, '다시 시작한 취미가 오래 이어지면 좋겠어요. 응원합니다.좋은 이야기 나눠 주셔서 고맙습니다.', 0, '2026-09-09 12:09:00', '2026-09-09 12:09:00'),
  (250, 250, 7, '정리한 자리만큼 새로운 여유가 생기는 것 같아요.좋은 이야기 나눠 주셔서 고맙습니다.', 0, '2026-09-10 12:10:00', '2026-09-10 12:10:00'),
  (251, 251, 8, '합정의 작은 책방 카페를 추천해요. 평일 오후에는 조용하고 의자도 편안했어요.', 0, '2026-09-11 12:11:00', '2026-09-11 12:11:00'),
  (252, 252, 9, '북한산 둘레길 8구간이 완만해서 처음 걷기 좋았어요. 지하철 접근성도 괜찮습니다.', 0, '2026-09-12 12:12:00', '2026-09-12 12:12:00'),
  (253, 253, 10, '스킨답서스가 잘 자라고 물 주는 시기를 놓쳐도 비교적 튼튼해서 추천해요.', 0, '2026-09-13 12:13:00', '2026-09-13 12:13:00'),
  (254, 254, 11, '빌 에반스의 앨범을 자주 들어요. 비 오는 저녁에 잘 어울립니다.', 0, '2026-09-14 12:14:00', '2026-09-14 12:14:00'),
  (255, 255, 12, '망원동의 독립서점들을 묶어서 돌아보세요. 한강까지 산책하기도 좋아요.', 0, '2026-09-15 12:15:00', '2026-09-15 12:15:00'),
  (256, 256, 13, '입문용으로 자동 노출이 되는 가벼운 모델부터 써 보시는 걸 추천합니다.', 0, '2026-09-16 12:16:00', '2026-09-16 12:16:00'),
  (257, 257, 14, '토마토 달걀 볶음이 빠르고 따뜻해서 혼자 먹는 저녁 메뉴로 좋아요.', 0, '2026-09-17 12:17:00', '2026-09-17 12:17:00'),
  (258, 258, 15, '팔당에서 양평 방향 길이 비교적 평탄하고 쉬어 갈 카페도 많아요.', 0, '2026-09-18 12:18:00', '2026-09-18 12:18:00'),
  (259, 259, 16, '컵 받침이나 작은 파우치부터 뜨면 완성하는 재미를 빨리 느낄 수 있어요.', 0, '2026-09-19 12:19:00', '2026-09-19 12:19:00'),
  (260, 260, 17, '포켓 크기의 무지 노트를 쓰고 있어요. 종이가 두꺼워 만년필도 잘 버팁니다.', 0, '2026-09-20 12:20:00', '2026-09-20 12:20:00'),
  (261, 261, 18, '합정의 작은 책방 카페를 추천해요. 평일 오후에는 조용하고 의자도 편안했어요. 추천하신 조건과도 잘 맞을 것 같아요.', 0, '2026-09-01 12:21:00', '2026-09-01 12:21:00'),
  (262, 262, 19, '북한산 둘레길 8구간이 완만해서 처음 걷기 좋았어요. 지하철 접근성도 괜찮습니다. 추천하신 조건과도 잘 맞을 것 같아요.', 0, '2026-09-02 12:22:00', '2026-09-02 12:22:00'),
