INSERT INTO report (id, member_id, target_id, post_id, reply_id, target_type, reason, status, created_at, updated_at) VALUES
  (1, 32, 7, 7, NULL, 'POST', '특정인을 겨냥한 모욕적인 표현이 반복적으로 포함되어 있습니다.', 'WAIT', '2026-09-04 15:01:00', NULL),
  (2, 33, 14, 14, NULL, 'POST', '사실과 다른 내용으로 개인의 명예를 훼손하고 있어 확인이 필요합니다.', 'WAIT', '2026-09-05 15:02:00', NULL),
  (3, 34, 21, 21, NULL, 'POST', '동의 없이 촬영된 것으로 보이는 타인의 얼굴이 그대로 노출되어 있습니다.', 'RESOLVED', '2026-09-06 15:03:00', '2026-09-20 16:03:00'),
  (4, 35, 28, 28, NULL, 'POST', '상품 판매를 유도하는 동일한 홍보 글을 여러 차례 게시하고 있습니다.', 'WAIT', '2026-09-07 15:04:00', NULL),
  (5, 36, 35, 35, NULL, 'POST', '폭력적인 장면이 별도 안내 없이 포함되어 있어 신고합니다.', 'WAIT', '2026-09-08 15:05:00', NULL),
  (6, 37, 42, 42, NULL, 'POST', '출처를 밝히지 않고 다른 창작자의 사진을 무단으로 사용한 것 같습니다.', 'RESOLVED', '2026-09-09 15:06:00', '2026-09-20 16:06:00'),
  (7, 38, 49, 49, NULL, 'POST', '개인 연락처와 주소로 추정되는 정보가 공개되어 있어 조치가 필요합니다.', 'WAIT', '2026-09-10 15:07:00', NULL),
  (8, 39, 6, 56, NULL, 'POST', '특정 집단을 비하하는 혐오 표현이 포함되어 있습니다.', 'WAIT', '2026-09-11 15:08:00', NULL),
  (9, 40, 13, 63, NULL, 'POST', '불법 거래로 의심되는 내용을 홍보하고 있어 검토를 요청합니다.', 'RESOLVED', '2026-09-12 15:09:00', '2026-09-20 16:09:00'),
  (10, 41, 20, 70, NULL, 'POST', '게시글 내용과 관계없는 도배성 해시태그와 링크가 반복됩니다.', 'WAIT', '2026-09-13 15:10:00', NULL),
  (11, 42, 12, NULL, 55, 'REPLY', '댓글에서 작성자에게 지속적으로 욕설과 인신공격을 하고 있습니다.', 'WAIT', '2026-09-14 15:11:00', NULL),
  (12, 43, 17, NULL, 60, 'REPLY', '다른 이용자를 사칭하며 허위 사실을 퍼뜨리는 댓글로 보입니다.', 'REJECTED', '2026-09-15 15:12:00', '2026-09-21 16:12:00'),
  (13, 44, 22, NULL, 65, 'REPLY', '같은 내용을 여러 게시글에 반복해서 남기는 스팸 계정입니다.', 'WAIT', '2026-09-16 15:13:00', NULL),
  (14, 45, 27, NULL, 70, 'REPLY', '성적인 표현이 포함된 불쾌한 댓글로 커뮤니티 이용에 방해가 됩니다.', 'WAIT', '2026-09-17 15:14:00', NULL),
  (15, 46, 32, NULL, 75, 'REPLY', '상대방의 개인정보를 알아내겠다는 위협성 내용이 포함되어 있습니다.', 'WAIT', '2026-09-18 15:15:00', NULL),
  (16, 47, 37, NULL, 80, 'REPLY', '논의와 무관하게 특정 지역과 출신을 비하하는 표현을 사용했습니다.', 'REJECTED', '2026-09-19 15:16:00', '2026-09-21 16:16:00'),
  (17, 48, 42, NULL, 85, 'REPLY', '게시글 작성자의 거절에도 광고 링크를 반복적으로 남기고 있습니다.', 'WAIT', '2026-09-03 15:17:00', NULL),
  (18, 49, 47, NULL, 90, 'REPLY', '다른 사용자를 조롱하도록 유도하는 악의적인 댓글입니다.', 'WAIT', '2026-09-04 15:18:00', NULL),
  (19, 50, 2, NULL, 95, 'REPLY', '금전 송금을 요구하며 외부 메신저로 대화를 유도하고 있습니다.', 'WAIT', '2026-09-05 15:19:00', NULL),
  (20, 1, 7, NULL, 100, 'REPLY', '범죄 행위를 구체적으로 조장하는 내용이 있어 빠른 확인을 요청합니다.', 'REJECTED', '2026-09-06 15:20:00', '2026-09-21 16:20:00');

INSERT INTO notification (id, receiver_id, sender_id, type, reference_id, content, is_read, created_at) VALUES
  (1, 1, 10, 'POST_LIKE', 1, '임채원님이 회원님의 게시글을 좋아합니다.', FALSE, '2026-09-04 16:01:00'),
  (2, 2, 11, 'REPLY', 2, '한지호님이 게시글에 새로운 답글을 작성했습니다.', FALSE, '2026-09-05 16:02:00'),
  (3, 3, 12, 'FOLLOW', 3, '오세아님이 앞으로 회원님의 소식을 받아봅니다.', TRUE, '2026-09-06 16:03:00'),
  (4, 4, 13, 'SUBSCRIPTION', 4, '신우진님이 회원님의 콘텐츠를 구독하기 시작했습니다.', FALSE, '2026-09-07 16:04:00'),
  (5, 5, 14, 'POST_LIKE', 5, '권나연님이 회원님의 새 게시글에 공감했어요.', FALSE, '2026-09-08 16:05:00'),
  (6, 6, 15, 'REPLY', 6, '황태윤님이 회원님의 이야기에 댓글로 참여했습니다.', TRUE, '2026-09-09 16:06:00'),
  (7, 7, 16, 'FOLLOW', 7, '안소희님이 회원님을 팔로우하기 시작했습니다.', FALSE, '2026-09-10 16:07:00'),
  (8, 8, 17, 'SUBSCRIPTION', 8, '송재민님이 새 구독자가 되었습니다.', FALSE, '2026-09-11 16:08:00'),
  (9, 9, 18, 'POST_LIKE', 9, '전유나님이 게시글에 좋아요를 남겼습니다.', TRUE, '2026-09-12 16:09:00'),
  (10, 10, 19, 'REPLY', 10, '홍성민님이 회원님의 게시글에 댓글을 남겼습니다.', FALSE, '2026-09-13 16:10:00'),
  (11, 11, 20, 'FOLLOW', 11, '고예린님이 회원님의 새 팔로워가 되었습니다.', FALSE, '2026-09-14 16:11:00'),
  (12, 12, 21, 'SUBSCRIPTION', 12, '문시우님이 회원님의 구독 멤버십에 가입했습니다.', TRUE, '2026-09-15 16:12:00'),
  (13, 13, 22, 'POST_LIKE', 13, '양다은님이 회원님의 게시글을 좋아합니다.', FALSE, '2026-09-16 16:13:00'),
  (14, 14, 23, 'REPLY', 14, '손건우님이 게시글에 새로운 답글을 작성했습니다.', FALSE, '2026-09-17 16:14:00'),
  (15, 15, 24, 'FOLLOW', 15, '배지민님이 앞으로 회원님의 소식을 받아봅니다.', TRUE, '2026-09-18 16:15:00'),
  (16, 16, 25, 'SUBSCRIPTION', 16, '백승현님이 회원님의 콘텐츠를 구독하기 시작했습니다.', FALSE, '2026-09-19 16:16:00'),
  (17, 17, 26, 'POST_LIKE', 17, '허아린님이 회원님의 새 게시글에 공감했어요.', FALSE, '2026-09-04 16:17:00'),
  (18, 18, 27, 'REPLY', 18, '남도현님이 회원님의 이야기에 댓글로 참여했습니다.', TRUE, '2026-09-05 16:18:00'),
  (19, 19, 28, 'FOLLOW', 19, '심가은님이 회원님을 팔로우하기 시작했습니다.', FALSE, '2026-09-06 16:19:00'),
  (20, 20, 29, 'SUBSCRIPTION', 20, '노정우님이 새 구독자가 되었습니다.', FALSE, '2026-09-07 16:20:00'),
  (21, 21, 30, 'POST_LIKE', 21, '하서윤님이 게시글에 좋아요를 남겼습니다.', TRUE, '2026-09-08 16:21:00'),
  (22, 22, 31, 'REPLY', 22, '서은호님이 회원님의 게시글에 댓글을 남겼습니다.', FALSE, '2026-09-09 16:22:00'),
  (23, 23, 32, 'FOLLOW', 23, '주혜원님이 회원님의 새 팔로워가 되었습니다.', FALSE, '2026-09-10 16:23:00'),
  (24, 24, 33, 'SUBSCRIPTION', 24, '구민재님이 회원님의 구독 멤버십에 가입했습니다.', TRUE, '2026-09-11 16:24:00'),
  (25, 25, 34, 'POST_LIKE', 25, '곽지아님이 회원님의 게시글을 좋아합니다.', FALSE, '2026-09-12 16:25:00'),
